// CalculateDiscount executes a JavaScript script in a Goja VM with order data
// injected as global variables, and returns the calculated discount as a float64.
func CalculateDiscount(script string, order map[string]interface{}) (float64, error) {
	vm := goja.New()

	// Set each key-value pair from the order map as a global variable
	// in the JavaScript runtime so scripts can access them directly.
	for key, val := range order {
